<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {useArcade} from '../stores/arcade'
import {api} from '../lib/api'
import {ticketKindMap} from '../data/ticketKinds'
const s=useArcade(),pending=ref([]),dialog=ref(null),busy=ref(false),error=ref(''),notice=ref('');let timer,epoch=0,fetching=false,seen=new Set()
function open(){error.value='';notice.value='';pending.value.forEach(g=>seen.add(g.id));if(!dialog.value.open)dialog.value.showModal()}
async function refresh(){if(s.user?.role!=='student'||document.visibilityState!=='visible'||fetching)return;const current=epoch;fetching=true;try{const r=await api('/tickets',{background:true});if(current!==epoch)return;pending.value=r.pending;if(pending.value.some(g=>!seen.has(g.id))&&!document.querySelector('dialog[open]'))open()}catch(e){if(current===epoch&&dialog.value?.open)error.value=e.message}finally{fetching=false}}
async function claim(id){if(busy.value)return;busy.value=true;error.value='';try{const r=await api('/tickets/'+id+'/claim',{method:'POST'});pending.value=r.pending;await s.refresh();notice.value='수령했어요! 마이 리틀 펫의 내 아이템 → 사용권에 보관됩니다.'}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>s.user?.id,()=>{epoch++;pending.value=[];seen=new Set();notice.value='';error.value='';dialog.value?.close();refresh()})
onMounted(()=>{refresh();timer=setInterval(refresh,15000);document.addEventListener('visibilitychange',refresh);window.addEventListener('spokemon-ticket-refresh',refresh)})
onUnmounted(()=>{epoch++;clearInterval(timer);document.removeEventListener('visibilitychange',refresh);window.removeEventListener('spokemon-ticket-refresh',refresh);dialog.value?.close()})
</script>
<template><template v-if="s.user?.role==='student'"><button class="profile-link ticket-inbox-button" :aria-label="'관리자 선물함 · 미수령 '+pending.length+'건'" @click="open">📦 선물함 <b v-if="pending.length" class="unread-badge">{{pending.length}}</b></button><dialog ref="dialog" class="ticket-dialog" aria-label="관리자 선물함" @cancel.prevent="!busy&&dialog.close()"><button class="text-button ticket-close" aria-label="선물함 닫기" :disabled="busy" @click="dialog.close()">✕</button><h2>🎁 관리자 선물함</h2><p v-if="pending.length">관리자 선물이 도착했어요!</p><p v-else>새로 도착한 선물이 없어요.</p><article v-for="g in pending" :key="g.id" class="received-gift"><strong>{{ticketKindMap[g.kind]?.icon}} {{ticketKindMap[g.kind]?.name}} {{g.quantity}}장</strong><p>{{g.sender}}님이 보냈어요 · {{new Date(g.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</p><p v-if="g.message">{{g.message}}</p><button :disabled="busy" @click="claim(g.id)">{{busy?'처리 중…':'수령하고 내 아이템에 저장'}}</button></article><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p><RouterLink to="/pet?items=tickets" class="button light" @click="dialog.close()">내 사용권 보기 →</RouterLink></dialog></template></template>
<style>
.ticket-dialog{box-sizing:border-box;width:min(600px,calc(100vw - 28px));max-height:88dvh;overflow:auto;border:3px solid var(--rpg-edge);border-radius:12px;padding:26px;background:var(--rpg-paper);color:var(--rpg-ink);box-shadow:inset 0 0 0 3px var(--rpg-bright),0 7px var(--rpg-shadow)}.ticket-dialog::backdrop{background:#17243399}.ticket-dialog h2{font-size:21px;margin:8px 24px 18px 0}.ticket-dialog p{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.ticket-close{position:absolute;right:10px;top:8px;margin:0}.ticket-dialog .toolbar{justify-content:flex-start;gap:10px;flex-wrap:wrap}.received-gift{padding:16px 0;border-top:1px solid var(--rpg-mid)}.received-gift strong{font-size:14px}.ticket-dialog button,.ticket-dialog .button{max-width:100%;white-space:normal;line-height:1.5}.ticket-inbox-button{gap:4px}@media(max-width:600px){.ticket-dialog{padding:20px 16px}.ticket-dialog h2{font-size:18px}.ticket-dialog button,.ticket-dialog .button{font-size:11px}}
</style>
